+</head>
+<body>
+  <div id="canvas-container"></div>
+
+  <div class="brand-header">
+    <h1>Gemini 4 Argon</h1>
+  </div>
+
+  <aside class="panel" aria-label="Lamp Controls">
+    <div class="row">
+      <span class="label">Power</span>
+      <button id="power-btn" class="power-btn" type="button">
+        <span class="power-dot"></span>
+        <span id="power-text">ON</span>
+      </button>
+    </div>
+
+    <div class="control-group">
+      <div class="row">
+        <span class="label">Colorway</span>
+        <span id="preset-label" class="preset-name">Classic Astro</span>
+      </div>
+      <div class="presets-grid" id="presets-grid"></div>
+    </div>
+
+    <div class="control-group">
+      <div class="row">
+        <span class="label">Heat / Flow</span>
+        <span id="heat-val" class="value-readout">100%</span>
+      </div>
+      <input id="heat-slider" type="range" min="0.4" max="1.8" step="0.02" value="1.0" />
+    </div>
+
+    <div class="control-group">
+      <div class="row">
+        <span class="label">Wax Volume</span>
+        <span id="wax-val" class="value-readout">100%</span>
+      </div>
+      <input id="wax-slider" type="range" min="0.55" max="1.40" step="0.02" value="1.0" />
+    </div>
+
+    <div class="control-group">
+      <div class="row">
+        <span class="label">Room Dimmer</span>
+        <span id="room-val" class="value-readout">30%</span>
+      </div>
+      <input id="room-slider" type="range" min="0.0" max="1.0" step="0.02" value="0.30" />
+    </div>
+
+    <div class="divider"></div>
+
+    <div class="toggles-row">
+      <button id="orbit-btn" class="chip-btn" type="button">Auto-Orbit</button>
+      <button id="slowmo-btn" class="chip-btn" type="button">Slow-Mo</button>
+    </div>
+  </aside>
+
+  <div class="hint-bar">Drag to orbit · Scroll to zoom · Click cord switch to toggle power</div>
+
+  <script type="module">
+    import * as THREE from 'three';
+    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
+    import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
+    import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
+    import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
+    import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
+    import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
+    import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
+
+    // ============================================================================
+    // 1. COLOR PRESETS
+    // ============================================================================
+    const PRESETS = [
+      {
+        name: 'Classic Astro',
+        waxHot: '#ff3a08',
+        waxCool: '#8c0612',
+        waxGlow: '#ff7718',
+        liquidTop: '#ffc414',
+        liquidBot: '#ff6a00',
+        bulbColor: '#ff7828',
+        swatch: 'linear-gradient(135deg, #ff3a08 45%, #ffc414 100%)'
+      },
+      {
+        name: 'Acid Cyber',
+        waxHot: '#52ff18',
+        waxCool: '#087d2e',
+        waxGlow: '#a4ff33',
+        liquidTop: '#063d96',
+        liquidBot: '#068596',
+        bulbColor: '#66ff44',
+        swatch: 'linear-gradient(135deg, #52ff18 45%, #0648a8 100%)'
+      },
+      {
+        name: 'Ultraviolet',
+        waxHot: '#ff1e8e',
+        waxCool: '#6c065c',
+        waxGlow: '#ff5eb5',
+        liquidTop: '#240b59',
+        liquidBot: '#59127a',
+        bulbColor: '#ff38a8',
+        swatch: 'linear-gradient(135deg, #ff1e8e 45%, #2b0f66 100%)'
+      },
+      {
+        name: 'Deep Lagoon',
+        waxHot: '#00f6ff',
+        waxCool: '#004885',
+        waxGlow: '#6efffa',
+        liquidTop: '#061436',
+        liquidBot: '#093466',
+        bulbColor: '#26e2ff',
+        swatch: 'linear-gradient(135deg, #00f6ff 45%, #081b47 100%)'
+      },
+      {
+        name: 'Molten Gold',
+        waxHot: '#ffaa00',
+        waxCool: '#7a2500',
+        waxGlow: '#ffdd44',
+        liquidTop: '#33061a',
+        liquidBot: '#730f1c',
+        bulbColor: '#ff9d1c',
+        swatch: 'linear-gradient(135deg, #ffaa00 45%, #470824 100%)'
+      }
+    ];
+
+    // ============================================================================
+    // 2. LAMP GEOMETRY PROFILE CONSTANTS
+    // ============================================================================
+    // Coordinates in world units (1 unit ~ 5 cm; total lamp height ~ 8.85 units ~ 44cm)
+    // Base cone: y = 0.0 to 2.55
+    // Glass visible section: y = 2.50 to 7.55
+    // Metal cap: y = 7.45 to 8.85
+    const GLASS_Y_BOT = 2.48;
+    const GLASS_Y_TOP = 7.56;
+    const GLASS_Y_MID = 3.22; // widest point (hip of the Astro bottle)
+
+    function getGlassOuterRadius(y) {
+      if (y <= GLASS_Y_MID) {
+        const t = THREE.MathUtils.clamp((y - GLASS_Y_BOT) / (GLASS_Y_MID - GLASS_Y_BOT), 0, 1);
+        return THREE.MathUtils.lerp(0.84, 1.24, Math.sin(t * Math.PI * 0.5));
+      } else {
+        const t = THREE.MathUtils.clamp((y - GLASS_Y_MID) / (GLASS_Y_TOP - GLASS_Y_MID), 0, 1);
+        // Classic straight conical taper with subtle curve near cap
+        return THREE.MathUtils.lerp(1.24, 0.67, t);
+      }
+    }
+
+    function getFluidRadius(y) {
+      return getGlassOuterRadius(y) - 0.075;
+    }
+
+    // ============================================================================
+    // 3. SCENE, CAMERA, RENDERER
+    // ============================================================================
+    const container = document.getElementById('canvas-container');
+    const renderer = new THREE.WebGLRenderer({
+      antialias: true,
+      powerPreference: 'high-performance'
+    });
+    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
+    renderer.setSize(window.innerWidth, window.innerHeight);
+    renderer.shadowMap.enabled = true;
+    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
+    renderer.toneMapping = THREE.ACESFilmicToneMapping;
+    renderer.toneMappingExposure = 1.05;
+    container.appendChild(renderer.domElement);
+
+    const scene = new THREE.Scene();
+    scene.background = new THREE.Color(0x050508);
+    scene.fog = new THREE.FogExp2(0x050508, 0.022);
+
+    // Generate studio/room environment map for realistic metal & glass reflections
+    const pmremGenerator = new THREE.PMREMGenerator(renderer);
+    pmremGenerator.compileEquirectangularShader();
+    const roomEnv = new RoomEnvironment();
+    const envMap = pmremGenerator.fromScene(roomEnv, 0.04).texture;
+    scene.environment = envMap;
+    roomEnv.dispose();
+
+    const camera = new THREE.PerspectiveCamera(
+      36,
+      window.innerWidth / window.innerHeight,
+      0.1,
+      80
+    );
+    camera.position.set(0.0, 5.5, 13.8);
+
+    const controls = new OrbitControls(camera, renderer.domElement);
+    controls.target.set(0, 4.75, 0);
+    controls.enableDamping = true;
+    controls.dampingFactor = 0.055;
+    controls.enablePan = false;
+    controls.minDistance = 5.2;
+    controls.maxDistance = 22.0;
+    controls.minPolarAngle = 0.18;
+    controls.maxPolarAngle = Math.PI * 0.492; // Stay above table plane
+    controls.autoRotate = false;
+    controls.autoRotateSpeed = 0.65;
+    controls.update();
+
+    // ============================================================================
+    // 4. PROCEDURAL TEXTURES (WOOD, BRUSHED METAL, WALL PLASTER, BOOK COVER)
+    // ============================================================================
+    function createWoodTextures() {
+      const size = 1024;
+      const colorCanvas = document.createElement('canvas');
+      const roughCanvas = document.createElement('canvas');
+      const bumpCanvas = document.createElement('canvas');
+      colorCanvas.width = roughCanvas.width = bumpCanvas.width = size;
+      colorCanvas.height = roughCanvas.height = bumpCanvas.height = size;
+
+      const cCtx = colorCanvas.getContext('2d');
+      const rCtx = roughCanvas.getContext('2d');
+      const bCtx = bumpCanvas.getContext('2d');
+
+      const cImg = cCtx.createImageData(size, size);
+      const rImg = rCtx.createImageData(size, size);
+      const bImg = bCtx.createImageData(size, size);
+
+      function hash(x, y) {
+        const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
+        return n - Math.floor(n);
+      }
+
+      function valueNoise(x, y) {
+        const ix = Math.floor(x);
+        const iy = Math.floor(y);
+        const fx = x - ix;
+        const fy = y - iy;
+        const ux = fx * fx * (3 - 2 * fx);
+        const uy = fy * fy * (3 - 2 * fy);
+        const a = hash(ix, iy);
+        const b = hash(ix + 1, iy);
+        const c = hash(ix, iy + 1);
+        const d = hash(ix + 1, iy + 1);
+        return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
+      }
+
+      function fbm(x, y) {
+        let v = 0;
+        let amp = 0.5;
+        for (let i = 0; i < 4; i++) {
+          v += amp * valueNoise(x, y);
+          x *= 2.02;
+          y *= 2.02;
+          amp *= 0.5;
+        }
+        return v;
+      }
+
+      for (let y = 0; y < size; y++) {
+        for (let x = 0; x < size; x++) {
+          const u = x / size;
+          const v = y / size;
+
+          const warp = fbm(u * 4.0, v * 4.0) * 1.6;
+          const ring = Math.sin((v * 20.0 + warp) * Math.PI * 2.0) * 0.5 + 0.5;
+          const fine = valueNoise(u * 180.0, v * 28.0);
+          const pores = valueNoise(u * 320.0, v * 45.0);
+
+          const grain = ring * 0.65 + fine * 0.25 + pores * 0.1;
+
+          // Rich dark walnut color
+          const r = Math.floor(THREE.MathUtils.lerp(28, 66, grain));
+          const g = Math.floor(THREE.MathUtils.lerp(16, 40, grain));
+          const b = Math.floor(THREE.MathUtils.lerp(11, 26, grain));
+
+          const idx = (y * size + x) * 4;
+          cImg.data[idx] = r;
+          cImg.data[idx + 1] = g;
+          cImg.data[idx + 2] = b;
+          cImg.data[idx + 3] = 255;
+
+          // Satin walnut roughness (105..165 out of 255 -> ~0.41..0.65)
+          const roughVal = Math.floor(THREE.MathUtils.lerp(155, 102, grain * 0.8 + pores * 0.2));
+          rImg.data[idx] = roughVal;
+          rImg.data[idx + 1] = roughVal;
+          rImg.data[idx + 2] = roughVal;
+          rImg.data[idx + 3] = 255;
+
+          const bumpVal = Math.floor(THREE.MathUtils.lerp(90, 175, fine * 0.6 + pores * 0.4));
+          bImg.data[idx] = bumpVal;
+          bImg.data[idx + 1] = bumpVal;
+          bImg.data[idx + 2] = bumpVal;
+          bImg.data[idx + 3] = 255;
+        }
+      }
+
+      cCtx.putImageData(cImg, 0, 0);
+      rCtx.putImageData(rImg, 0, 0);
+      bCtx.putImageData(bImg, 0, 0);
+
+      const map = new THREE.CanvasTexture(colorCanvas);
+      const roughnessMap = new THREE.CanvasTexture(roughCanvas);
+      const bumpMap = new THREE.CanvasTexture(bumpCanvas);
+
+      map.colorSpace = THREE.SRGBColorSpace;
+      [map, roughnessMap, bumpMap].forEach((t) => {
+        t.wrapS = t.wrapT = THREE.RepeatWrapping;
+        t.repeat.set(3, 3);
+        t.anisotropy = 8;
+      });
+
+      return { map, roughnessMap, bumpMap };
+    }
+
+    function createBrushedMetalTexture() {
+      const w = 512, h = 256;
+      const canvas = document.createElement('canvas');
+      canvas.width = w;
+      canvas.height = h;
+      const ctx = canvas.getContext('2d');
+      const img = ctx.createImageData(w, h);
+
+      for (let y = 0; y < h; y++) {
+        const streak = (Math.random() - 0.5) * 34;
+        const fineWave = Math.sin(y * 0.45) * 8;
+        for (let x = 0; x < w; x++) {
+          const n = (Math.random() - 0.5) * 10;
+          const v = THREE.MathUtils.clamp(Math.floor(135 + streak + fineWave + n), 85, 200);
+          const idx = (y * w + x) * 4;
+          img.data[idx] = v;
+          img.data[idx + 1] = v;
+          img.data[idx + 2] = v;
+          img.data[idx + 3] = 255;
+        }
+      }
+      ctx.putImageData(img, 0, 0);
+      const tex = new THREE.CanvasTexture(canvas);
+      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
+      tex.repeat.set(2, 1);
+      return tex;
+    }
+
+    const woodTex = createWoodTextures();
+    const brushedTex = createBrushedMetalTexture();
+
+    // ============================================================================
+    // 5. ROOM & PROPS (TABLE, BACKDROP WALL, BOOKS, CERAMIC COASTER/MUG)
+    // ============================================================================
+    const roomGroup = new THREE.Group();
+    scene.add(roomGroup);
+
+    // Table surface
+    const tableGeo = new THREE.CylinderGeometry(16, 16, 0.6, 64);
+    const tableMat = new THREE.MeshStandardMaterial({
+      map: woodTex.map,
+      roughnessMap: woodTex.roughnessMap,
+      bumpMap: woodTex.bumpMap,
+      bumpScale: 0.015,
+      roughness: 0.72,
+      metalness: 0.05,
+      envMapIntensity: 0.35
+    });
+    const tableMesh = new THREE.Mesh(tableGeo, tableMat);
+    tableMesh.position.y = -0.3;
+    tableMesh.receiveShadow = true;
+    roomGroup.add(tableMesh);
+
+    // Curved dark plaster wall behind the table
+    const wallGeo = new THREE.CylinderGeometry(18, 18, 26, 64, 1, true, Math.PI * 0.6, Math.PI * 0.8);
+    wallGeo.scale(-1, 1, -1);
+    const wallMat = new THREE.MeshStandardMaterial({
+      color: 0x12131a,
+      roughness: 0.92,
+      metalness: 0.02,
+      bumpMap: woodTex.bumpMap,
+      bumpScale: 0.008,
+      envMapIntensity: 0.15
+    });
+    const wallMesh = new THREE.Mesh(wallGeo, wallMat);
+    wallMesh.position.set(0, 10, 0);
+    wallMesh.receiveShadow = true;
+    roomGroup.add(wallMesh);
+
+    // Subtle acoustic wooden slats on the left background wall to catch warm rim light
+    const slatMat = new THREE.MeshStandardMaterial({
+      color: 0x241710,
+      roughness: 0.65,
+      metalness: 0.05,
+      envMapIntensity: 0.25
