+      opacity: 0.11,
+      depthWrite: false,
+      side: THREE.BackSide
+    });
+    const glassBackMesh = new THREE.Mesh(glassGeo, glassBackMat);
+    glassBackMesh.scale.set(0.96, 1.0, 0.96);
+    glassBackMesh.renderOrder = 1;
+    lampGroup.add(glassBackMesh);
+
+    // ============================================================================
+    // 8. LIGHTING (DYNAMIC FLICKERING LAMP LIGHTS + DIMMABLE ROOM LIGHTS)
+    // ============================================================================
+    // Primary light emitted by the lava column & bulb onto the table and wall
+    const lampMainLight = new THREE.PointLight(0xff6a1a, 14.0, 26.0, 1.65);
+    lampMainLight.position.set(0, 3.8, 0);
+    lampMainLight.castShadow = true;
+    lampMainLight.shadow.mapSize.width = 1024;
+    lampMainLight.shadow.mapSize.height = 1024;
+    lampMainLight.shadow.bias = -0.0008;
+    lampMainLight.shadow.radius = 5;
+    scene.add(lampMainLight);
+
+    // Lower warm spill light right above the metal base collar
+    const lampBaseLight = new THREE.PointLight(0xff5510, 7.5, 14.0, 1.8);
+    lampBaseLight.position.set(0, 2.75, 0);
+    scene.add(lampBaseLight);
+
+    // Ambient & subtle directional key light for the dim room
+    const roomAmbient = new THREE.HemisphereLight(0x3a4866, 0x14100d, 0.42);
+    scene.add(roomAmbient);
+
+    const roomKeyLight = new THREE.DirectionalLight(0x9ab0d6, 0.55);
+    roomKeyLight.position.set(6.5, 11.5, 7.5);
+    roomKeyLight.castShadow = true;
+    roomKeyLight.shadow.mapSize.width = 1024;
+    roomKeyLight.shadow.mapSize.height = 1024;
+    roomKeyLight.shadow.camera.near = 1;
+    roomKeyLight.shadow.camera.far = 30;
+    const d = 10;
+    roomKeyLight.shadow.camera.left = -d;
+    roomKeyLight.shadow.camera.right = d;
+    roomKeyLight.shadow.camera.top = d;
+    roomKeyLight.shadow.camera.bottom = -d;
+    roomKeyLight.shadow.bias = -0.0005;
+    scene.add(roomKeyLight);
+
+    // ============================================================================
+    // 9. POST-PROCESSING (BLOOM + SUBTLE CINEMATIC VIGNETTE & FILM GRAIN)
+    // ============================================================================
+    const composer = new EffectComposer(renderer);
+    composer.addPass(new RenderPass(scene, camera));
+
+    const bloomPass = new UnrealBloomPass(
+      new THREE.Vector2(window.innerWidth, window.innerHeight),
+      0.42, // strength
+      0.65, // radius
+      0.72  // threshold
+    );
+    composer.addPass(bloomPass);
+
+    const CinematicShader = {
+      uniforms: {
+        tDiffuse: { value: null },
+        uTime: { value: 0 }
+      },
+      vertexShader: /* glsl */ `
+        varying vec2 vUv;
+        void main() {
+          vUv = uv;
+          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
+        }
+      `,
+      fragmentShader: /* glsl */ `
+        uniform sampler2D tDiffuse;
+        uniform float uTime;
+        varying vec2 vUv;
+
+        float rand(vec2 co) {
+          return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
+        }
+
+        void main() {
+          vec4 tex = texture2D(tDiffuse, vUv);
+          vec2 centered = vUv - 0.5;
+          float vig = 1.0 - dot(centered, centered) * 0.42;
+          float grain = (rand(vUv + fract(uTime * 0.37)) - 0.5) * 0.014;
+          gl_FragColor = vec4(max(tex.rgb * vig + grain, vec3(0.0)), tex.a);
+        }
+      `
+    };
+    const cinematicPass = new ShaderPass(CinematicShader);
+    composer.addPass(cinematicPass);
+
+    const outputPass = new OutputPass();
+    composer.addPass(outputPass);
+
+    // ============================================================================
+    // 10. THERMODYNAMIC WAX SIMULATION (FIXED TIMESTEP)
+    // ============================================================================
+    const state = {
+      power: true,
+      powerLevel: 1.0,     // Smooth bulb brightness transition
+      warmthLevel: 1.0,    // Thermal inertia of the wax (warms up / cools down gradually)
+      heatSetting: 1.0,    // User heat / flow speed multiplier
+      waxVolume: 1.0,      // User wax amount multiplier
+      roomDimmer: 0.30,    // Room ambient level
+      slowMo: false,
+      presetIndex: 0
+    };
+
+    // Create 18 blobs: 13 primary thermal blobs + 5 satellite pinch droplets
+    const blobs = [];
+    for (let i = 0; i < MAX_BLOBS; i++) {
+      const isDroplet = i >= 13;
+      // Distribute initial heights and temperatures so the lamp is in full lively motion immediately on load
+      const tNorm = (i % 13) / 13;
+      const startY = isDroplet
+        ? 3.1 + (i - 13) * 0.85
+        : 2.75 + tNorm * 4.25;
+      const angle = i * 2.39996; // Golden angle distribution
+      const rad = isDroplet ? 0.14 : (0.12 + (i % 3) * 0.11);
+
+      // Blobs in the first half are warm and rising; second half are cooling and sinking
+      const initialTemp = (i % 2 === 0)
+        ? 0.62 + (i % 5) * 0.07
+        : 0.25 + (i % 4) * 0.06;
+
+      const initialVy = (initialTemp - 0.48) * 0.55;
+
+      blobs.push({
+        x: Math.cos(angle) * rad,
+        y: startY,
+        z: Math.sin(angle) * rad,
+        vx: 0,
+        vy: initialVy,
+        vz: 0,
+        baseRadius: isDroplet
+          ? 0.14 + (i % 3) * 0.025
+          : 0.23 + ((i * 7) % 5) * 0.028,
+        radius: 0.25,
+        temp: initialTemp,
+        stretch: 1.0,
+        phase: i * 1.71 + 0.5,
+        freq: 0.55 + (i % 7) * 0.11,
+        isDroplet,
+        parentIdx: i % 13
+      });
+    }
+
+    const FIXED_DT = 1 / 60;
+    let simTime = 12.0; // Start offset so noise patterns are well-developed
+
+    function stepSimulation(dt) {
+      simTime += dt;
+
+      // 1. Update power & thermal inertia
+      const targetPower = state.power ? 1.0 : 0.0;
+      state.powerLevel += (targetPower - state.powerLevel) * Math.min(1.0, dt * 3.8);
+
+      // When turned off, wax cools down over ~6 seconds. When turned back on, wax warms up over ~4.5 seconds.
+      const targetWarmth = state.power ? 1.0 : 0.0;
+      const warmthRate = state.power ? 0.26 : 0.22;
+      state.warmthLevel += (targetWarmth - state.warmthLevel) * Math.min(1.0, dt * warmthRate);
+
+      const effectiveHeat = state.heatSetting * state.warmthLevel;
+      const flowSpeed = 0.55 + 0.65 * effectiveHeat;
+
+      // 2. Update each blob's thermodynamics, buoyancy, necking, and vessel confinement
+      for (let i = 0; i < MAX_BLOBS; i++) {
+        const b = blobs[i];
+        const hNorm = THREE.MathUtils.clamp((b.y - GLASS_Y_BOT) / (GLASS_Y_TOP - GLASS_Y_BOT), 0.0, 1.0);
+
+        if (!state.power && state.warmthLevel < 0.35) {
+          // Lamp is cooling/off: all blobs lose heat and sink gently into the bottom pool
+          b.temp += (0.12 - b.temp) * dt * 0.65;
+        } else {
+          // Heating zone at the bottom near the bulb (hNorm < 0.22)
+          if (hNorm < 0.22) {
+            const heatGain = (1.0 - hNorm / 0.22) * (0.42 + 0.35 * state.heatSetting) * state.warmthLevel;
+            b.temp += (0.96 - b.temp) * heatGain * dt;
+          }
+          // Cooling zone near the metal cap at the top (hNorm > 0.72)
+          else if (hNorm > 0.72) {
+            const coolLoss = ((hNorm - 0.72) / 0.28) * 0.52;
+            b.temp += (0.08 - b.temp) * coolLoss * dt;
+          }
+          // Ambient radiative cooling in the middle column
+          else {
+            const midTarget = 0.44 + 0.06 * Math.sin(simTime * b.freq + b.phase);
+            b.temp += (midTarget - b.temp) * 0.07 * dt;
+          }
+        }
+
+        b.temp = THREE.MathUtils.clamp(b.temp, 0.05, 0.98);
+
+        // Thermal expansion: warmer wax expands slightly
+        const thermalExpansion = 0.93 + 0.14 * b.temp;
+        const volumeFactor = Math.pow(state.waxVolume, 0.45);
+        b.radius = b.baseRadius * thermalExpansion * volumeFactor;
+
+        // Buoyancy force: neutral buoyancy at temp = 0.48
+        const neutralTemp = 0.48 - (state.heatSetting - 1.0) * 0.05;
+        let buoyancy = (b.temp - neutralTemp) * 0.92 * flowSpeed;
+
+        // Falling cold blobs are slightly denser and steadier; rising hot blobs accelerate smoothly
+        if (buoyancy < 0) {
+          buoyancy *= 0.78;
+        }
+
+        // When lamp is turned off, pull wax down into the bottom pool
+        if (!state.power) {
+          buoyancy -= (1.0 - state.warmthLevel) * 0.65;
+        }
+
+        // Surface-tension dwell at the bottom pool before necking off and rising
+        if (hNorm < 0.12 && b.vy > 0 && b.temp < 0.66) {
+          buoyancy *= 0.25;
+        }
+
+        // Gentle convective swirl inside the fluid column
+        const swirlAngle = simTime * b.freq + b.phase + b.y * 0.65;
+        const swirlStrength = (0.14 + 0.12 * effectiveHeat) * (0.3 + 0.7 * Math.sin(hNorm * Math.PI));
+        const fx = Math.cos(swirlAngle) * swirlStrength - b.x * 0.35;
+        const fz = Math.sin(swirlAngle * 1.13) * swirlStrength - b.z * 0.35;
+
+        b.vx += fx * dt;
+        b.vz += fz * dt;
+        b.vy += buoyancy * dt;
+
+        // Soft pairwise interaction: nearby blobs at similar temperatures gently attract to merge,
+        // while satellite droplets pinch off behind fast-rising parent blobs
+        if (b.isDroplet) {
+          const parent = blobs[b.parentIdx];
+          if (parent && parent.vy > 0.18 && hNorm > 0.25 && hNorm < 0.78 && state.warmthLevel > 0.5) {
+            // Trail slightly below the rising parent blob so it necks and pinches off organically
+            const targetY = parent.y - (parent.radius + b.radius) * 1.25;
+            b.vx += (parent.x - b.x) * 1.8 * dt;
+            b.vz += (parent.z - b.z) * 1.8 * dt;
+            b.vy += (targetY - b.y) * 1.2 * dt;
+          }
+        } else {
+          for (let j = i + 1; j < 13; j++) {
+            const o = blobs[j];
+            const dx = o.x - b.x;
+            const dy = o.y - b.y;
+            const dz = o.z - b.z;
+            const distSq = dx * dx + dy * dy + dz * dz;
+            const minDist = (b.radius + o.radius) * 0.85;
+            if (distSq < minDist * minDist && distSq > 0.0001) {
+              const dist = Math.sqrt(distSq);
+              // Prevent complete collapse to identical centers so blobs remain rich and varied
+              const push = (minDist - dist) * 0.45 * dt;
+              const nx = dx / dist;
+              const ny = dy / dist;
+              const nz = dz / dist;
+              b.vx -= nx * push;
+              b.vy -= ny * push * 0.4;
+              b.vz -= nz * push;
+              o.vx += nx * push;
+              o.vy += ny * push * 0.4;
+              o.vz += nz * push;
+            }
+          }
+        }
+
+        // Viscous fluid damping
+        const damping = Math.exp(-1.55 * dt);
+        b.vx *= damping;
+        b.vy *= damping;
+        b.vz *= damping;
+
+        // Clamp max vertical velocity
+        b.vy = THREE.MathUtils.clamp(b.vy, -0.58, 0.68);
+
+        // Advance position
+        b.x += b.vx * dt;
+        b.y += b.vy * dt;
+        b.z += b.vz * dt;
+
+        // Vertical floor & ceiling bounds inside the vessel
+        const minY = GLASS_Y_BOT + 0.14 + b.radius * 0.55;
+        const maxY = GLASS_Y_TOP - 0.18 - b.radius * 0.65;
+        if (b.y < minY) {
+          b.y = minY;
+          if (b.vy < 0) b.vy *= -0.2;
+        } else if (b.y > maxY) {
+          b.y = maxY;
+          if (b.vy > 0) b.vy *= -0.25;
+        }
+
+        // Constrain radial position inside the tapered glass wall
+        const allowedR = Math.max(0.06, getFluidRadius(b.y) - b.radius * 0.92 - 0.05);
+        const currR = Math.hypot(b.x, b.z);
+        if (currR > allowedR) {
+          const scale = allowedR / currR;
+          b.x *= scale;
+          b.z *= scale;
+          b.vx *= -0.35;
+          b.vz *= -0.35;
+        }
+
+        // Compute vertical stretching: rising warm blobs elongate, pool/cap blobs flatten slightly
+        const speedStretch = 1.0 + b.vy * 0.48 + Math.abs(b.vy) * 0.18;
+        const boundarySquash = (hNorm < 0.08 || hNorm > 0.92) ? 0.86 : 1.0;
+        const targetStretch = THREE.MathUtils.clamp(speedStretch * boundarySquash, 0.78, 1.48);
+        b.stretch += (targetStretch - b.stretch) * Math.min(1.0, dt * 6.0);
+
+        // Write to shader uniform arrays
+        blobUniformArray[i].set(b.x, b.y, b.z, b.radius);
+        stretchUniformArray[i] = b.stretch;
+      }
+
+      // 3. Calculate optical occlusion of the bottom bulb by nearby wax blobs
+      // As large blobs gather or detach right above the bulb, the room light shifts & flickers naturally
+      let occlusion = 0.0;
+      let centerOfMassY = 0.0;
+      let totalWeight = 0.0;
+
+      for (let i = 0; i < MAX_BLOBS; i++) {
+        const b = blobs[i];
+        if (b.y < 4.2) {
+          const hFactor = 1.0 - THREE.MathUtils.clamp((b.y - 2.5) / 1.7, 0.0, 1.0);
+          const rDist = Math.hypot(b.x, b.z);
+          const centerFactor = Math.exp(-rDist * rDist * 3.5);
+          occlusion += hFactor * centerFactor * (b.radius * 1.4);
+        }
+        const w = b.radius * b.radius * b.radius;
+        centerOfMassY += b.y * w;
+        totalWeight += w;
+      }
+      centerOfMassY = totalWeight > 0 ? centerOfMassY / totalWeight : 3.8;
+
+      const flicker = THREE.MathUtils.clamp(1.0 - occlusion * 0.22 + Math.sin(simTime * 2.3) * 0.03, 0.62, 1.12);
+      const pwr = state.powerLevel;
+
+      lampMainLight.intensity = 14.5 * pwr * flicker;
+      lampMainLight.position.y = THREE.MathUtils.lerp(3.2, 4.4, (centerOfMassY - 2.6) / 4.2);
+      lampBaseLight.intensity = 7.8 * pwr * (0.85 + 0.15 * flicker);
+
+      bulbMat.emissiveIntensity = 3.8 * pwr;
+      rockerMat.emissiveIntensity = 0.45 * pwr;
+
+      // Update shader uniforms
+      fluidUniforms.uTime.value = simTime;
+      fluidUniforms.uPower.value = pwr;
+      fluidUniforms.uWarmth.value = state.warmthLevel;
+      fluidUniforms.uWaxScale.value = state.waxVolume;
+      fluidUniforms.uRoomLight.value = state.roomDimmer;
+    }
+
+    // ============================================================================
+    // 11. UI CONTROLS & INTERACTION WIRING
+    // ============================================================================
+    const powerBtn = document.getElementById('power-btn');
+    const powerText = document.getElementById('power-text');
+    const presetLabel = document.getElementById('preset-label');
+    const presetsGrid = document.getElementById('presets-grid');
+    const heatSlider = document.getElementById('heat-slider');
+    const heatVal = document.getElementById('heat-val');
+    const waxSlider = document.getElementById('wax-slider');
+    const waxVal = document.getElementById('wax-val');
+    const roomSlider = document.getElementById('room-slider');
+    const roomVal = document.getElementById('room-val');
+    const orbitBtn = document.getElementById('orbit-btn');
+    const slowmoBtn = document.getElementById('slowmo-btn');
+
+    function setPower(on) {
+      state.power = on;
+      powerBtn.classList.toggle('off', !on);
+      powerText.textContent = on ? 'ON' : 'OFF';
+      rockerMesh.rotation.x = on ? 0.18 : -0.18;
+    }
+
+    powerBtn.addEventListener('click', () => setPower(!state.power));
+
+    // Build preset swatches
+    PRESETS.forEach((p, idx) => {
+      const btn = document.createElement('button');
+      btn.type = 'button';
+      btn.className = 'preset-swatch' + (idx === 0 ? ' active' : '');
+      btn.style.background = p.swatch;
+      btn.title = p.name;
+      btn.addEventListener('click', () => applyPreset(idx));
+      presetsGrid.appendChild(btn);
+    });
+
+    const targetColors = {
+      waxHot: new THREE.Color(PRESETS[0].waxHot),
+      waxCool: new THREE.Color(PRESETS[0].waxCool),
+      waxGlow: new THREE.Color(PRESETS[0].waxGlow),
+      liquidTop: new THREE.Color(PRESETS[0].liquidTop),
+      liquidBot: new THREE.Color(PRESETS[0].liquidBot),
+      bulbColor: new THREE.Color(PRESETS[0].bulbColor)
+    };
+
+    function applyPreset(idx) {
+      state.presetIndex = idx;
+      const p = PRESETS[idx];
+      presetLabel.textContent = p.name;
+      document.querySelectorAll('.preset-swatch').forEach((el, i) => {
+        el.classList.toggle('active', i === idx);
+      });
+      targetColors.waxHot.set(p.waxHot);
+      targetColors.waxCool.set(p.waxCool);
+      targetColors.waxGlow.set(p.waxGlow);
+      targetColors.liquidTop.set(p.liquidTop);
+      targetColors.liquidBot.set(p.liquidBot);
+      targetColors.bulbColor.set(p.bulbColor);
+    }
+
+    heatSlider.addEventListener('input', (e) => {
+      state.heatSetting = parseFloat(e.target.value);
+      heatVal.textContent = `${Math.round(state.heatSetting * 100)}%`;
+    });
+
+    waxSlider.addEventListener('input', (e) => {
+      state.waxVolume = parseFloat(e.target.value);
+      waxVal.textContent = `${Math.round(state.waxVolume * 100)}%`;
+    });
+
+    function updateRoomLighting(level) {
+      state.roomDimmer = level;
+      roomVal.textContent = `${Math.round(level * 100)}%`;
+      roomAmbient.intensity = 0.08 + level * 1.15;
+      roomKeyLight.intensity = 0.05 + level * 1.65;
+    }
+
+    roomSlider.addEventListener('input', (e) => {
+      updateRoomLighting(parseFloat(e.target.value));
+    });
+    updateRoomLighting(state.roomDimmer);
+
+    orbitBtn.addEventListener('click', () => {
+      controls.autoRotate = !controls.autoRotate;
+      orbitBtn.classList.toggle('active', controls.autoRotate);
+    });
+
+    slowmoBtn.addEventListener('click', () => {
+      state.slowMo = !state.slowMo;
+      slowmoBtn.classList.toggle('active', state.slowMo);
+    });
+
+    // Raycast click on the physical 3D cord switch to toggle power
+    const raycaster = new THREE.Raycaster();
+    const pointer = new THREE.Vector2();
+    let pointerDownPos = { x: 0, y: 0 };
+
+    renderer.domElement.addEventListener('pointerdown', (e) => {
+      pointerDownPos.x = e.clientX;
+      pointerDownPos.y = e.clientY;
+    });
+
+    renderer.domElement.addEventListener('pointerup', (e) => {
+      const moveDist = Math.hypot(e.clientX - pointerDownPos.x, e.clientY - pointerDownPos.y);
+      if (moveDist > 6) return;
+
+      pointer.x = (e.clientX / window.innerWidth) * 2 - 1;
+      pointer.y = -(e.clientY / window.innerHeight) * 2 + 1;
+      raycaster.setFromCamera(pointer, camera);
+
+      const hits = raycaster.intersectObjects([switchBody, rockerMesh], false);
+      if (hits.length > 0) {
+        setPower(!state.power);
+      }
+    });
+
+    // Change cursor when hovering over the 3D cord switch
+    renderer.domElement.addEventListener('pointermove', (e) => {
+      pointer.x = (e.clientX / window.innerWidth) * 2 - 1;
+      pointer.y = -(e.clientY / window.innerHeight) * 2 + 1;
+      raycaster.setFromCamera(pointer, camera);
+      const hits = raycaster.intersectObjects([switchBody, rockerMesh], false);
+      renderer.domElement.style.cursor = hits.length > 0 ? 'pointer' : 'grab';
+    });
+
+    // ============================================================================
+    // 12. RESIZE & ANIMATION LOOP (WITH FIXED TIMESTEP ACCUMULATOR)
+    // ============================================================================
+    window.addEventListener('resize', () => {
+      const w = window.innerWidth;
+      const h = window.innerHeight;
+      camera.aspect = w / h;
+      camera.updateProjectionMatrix();
+      renderer.setSize(w, h);
+      composer.setSize(w, h);
+    });
+
+    // Pre-warm the physics simulation for 180 steps so blobs are naturally distributed on frame 1
+    for (let i = 0; i < 180; i++) {
+      stepSimulation(FIXED_DT);
+    }
+
+    let lastFrameTime = performance.now();
+    let accumulator = 0;
+
+    function animate(now) {
+      requestAnimationFrame(animate);
+
+      const rawDt = Math.min((now - lastFrameTime) / 1000, 0.1);
+      lastFrameTime = now;
+
+      const timeScale = state.slowMo ? 0.22 : 1.0;
+      accumulator += rawDt * timeScale;
+
+      // Advance physics with bounded fixed timestep so frame hitches never destabilize blobs
+      let substeps = 0;
+      while (accumulator >= FIXED_DT && substeps < 6) {
+        stepSimulation(FIXED_DT);
+        accumulator -= FIXED_DT;
+        substeps++;
+      }
+
+      // Smoothly interpolate colorway transitions
+      const colorLerp = Math.min(1.0, rawDt * 6.0);
+      fluidUniforms.uWaxHot.value.lerp(targetColors.waxHot, colorLerp);
+      fluidUniforms.uWaxCool.value.lerp(targetColors.waxCool, colorLerp);
+      fluidUniforms.uWaxGlow.value.lerp(targetColors.waxGlow, colorLerp);
+      fluidUniforms.uLiquidTop.value.lerp(targetColors.liquidTop, colorLerp);
+      fluidUniforms.uLiquidBot.value.lerp(targetColors.liquidBot, colorLerp);
+
+      lampMainLight.color.lerp(targetColors.bulbColor, colorLerp);
+      lampBaseLight.color.lerp(targetColors.waxHot, colorLerp);
+      bulbMat.emissive.lerp(targetColors.bulbColor, colorLerp);
+
+      cinematicPass.uniforms.uTime.value = now * 0.001;
+
+      controls.update();
+      composer.render();
+    }
+
+    requestAnimationFrame(animate);
+  </script>
+</body>
+</html>
